1	import { useEffect, useState } from "react";
2	import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
3	import { useLoaderData, useFetcher, useNavigate } from "react-router";
4	import { useAppBridge } from "@shopify/app-bridge-react";
5	import {
6	  Page,
7	  Layout,
8	  Card,
9	  BlockStack,
10	  InlineStack,
11	  Text,
12	  Badge,
13	  Button,
14	  TextField,
15	  Checkbox,
16	  Box,
17	  Divider,
18	  RangeSlider,
19	  Tooltip,
20	  InlineGrid,
21	} from "@shopify/polaris";
22	import { authenticate } from "../shopify.server";
23	import db from "../db.server";
24	
25	// ---------------------------------------------------------------------------
26	// Types
27	// ---------------------------------------------------------------------------
28	
29	interface LocalConfig {
30	  displayMode: string;
31	  position: string;
32	  triggerType: string;
33	  primaryColor: string;
34	  successColor: string;
35	  errorColor: string;
36	  backgroundColor: string;
37	  textColor: string;
38	  borderRadius: string;
39	  heading: string;
40	  placeholder: string;
41	  buttonText: string;
42	  successMessage: string;
43	  errorMessage: string;
44	  showRecommender: boolean;
45	  customCss: string;
46	}
47	
48	// ---------------------------------------------------------------------------
49	// Loader
50	// ---------------------------------------------------------------------------
51	
52	export const loader = async ({ request }: LoaderFunctionArgs) => {
53	  const { session } = await authenticate.admin(request);
54	  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });
55	
56	  return {
57	    config: config ?? {
58	      displayMode: "popup",
59	      position: "bottom-right",
60	      triggerType: "button",
61	      primaryColor: "#000000",
62	      successColor: "#16a34a",
63	      errorColor: "#dc2626",
64	      backgroundColor: "#ffffff",
65	      textColor: "#111111",
66	      borderRadius: "8",
67	      heading: "Size Guide",
68	      placeholder: "Select your size",
69	      buttonText: "Find My Size",
70	      successMessage: "This size should fit you well!",
71	      errorMessage: "We couldn't determine your size. Please refer to the chart.",
72	      showRecommender: true,
73	      customCss: "",
74	    },
75	  };
76	};
77	
78	// ---------------------------------------------------------------------------
79	// Action
80	// ---------------------------------------------------------------------------
81	
82	export const action = async ({ request }: ActionFunctionArgs) => {
83	  const { session } = await authenticate.admin(request);
84	  const formData = await request.formData();
85	
86	  try {
87	    const data = {
88	      displayMode: (formData.get("displayMode") as string) || "popup",
89	      position: (formData.get("position") as string) || "bottom-right",
90	      triggerType: (formData.get("triggerType") as string) || "button",
91	      primaryColor: (formData.get("primaryColor") as string) || "#000000",
92	      successColor: (formData.get("successColor") as string) || "#16a34a",
93	      errorColor: (formData.get("errorColor") as string) || "#dc2626",
94	      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
95	      textColor: (formData.get("textColor") as string) || "#111111",
96	      borderRadius: (formData.get("borderRadius") as string) || "8",
97	      heading: (formData.get("heading") as string) || "Size Guide",
98	      placeholder: (formData.get("placeholder") as string) || "Select your size",
99	      buttonText: (formData.get("buttonText") as string) || "Find My Size",
100	      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
101	      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
102	      showRecommender: formData.get("showRecommender") === "true",
103	      customCss: (formData.get("customCss") as string) || "",
104	    };
105	
106	    await db.widgetConfig.upsert({
107	      where: { shop: session.shop },
108	      update: data,
109	      create: { shop: session.shop, ...data },
110	    });
111	    return { ok: true, message: "Widget settings saved" };
112	  } catch (error) {
113	    return {
114	      error: error instanceof Error ? error.message : "An unexpected error occurred",
115	    };
116	  }
117	};
118	
119	// ---------------------------------------------------------------------------
120	// Sub-components
121	// ---------------------------------------------------------------------------
122	
123	function ColorPickerField({
124	  label,
125	  value,
126	  onChange,
127	}: {
128	  label: string;
129	  value: string;
130	  onChange: (v: string) => void;
131	}) {
132	  return (
133	    <Card>
134	      <BlockStack gap="200">
135	        <Text as="p" variant="bodyMd">{label}</Text>
136	        <InlineStack gap="200" blockAlign="center">
137	          <Box
138	            borderWidth="025"
139	            borderColor="border"
140	            borderRadius="200"
141	            minWidth="44px"
142	            minHeight="44px"
143	            overflowX="hidden"
144	            overflowY="hidden"
145	          >
146	            <div style={{ position: "relative", width: "44px", height: "44px" }}>
147	              <input
148	                type="color"
149	                value={value}
150	                onChange={(e) => onChange(e.target.value)}
151	                aria-label={label}
152	                style={{
153	                  position: "absolute",
154	                  inset: 0,
155	                  opacity: 0,
156	                  width: "100%",
157	                  height: "100%",
158	                  cursor: "pointer",
159	                  padding: 0,
160	                  border: "none",
161	                }}
162	              />
163	              <div style={{ width: "100%", height: "100%", backgroundColor: value }} />
164	            </div>
165	          </Box>
166	          <TextField
167	            label=""
168	            labelHidden
169	            value={value}
170	            onChange={(val) => onChange(val)}
171	            maxLength={7}
172	            autoComplete="off"
173	          />
174	        </InlineStack>
175	      </BlockStack>
176	    </Card>
177	  );
178	}
179	
180	function DisplayModeCard({
181	  value,
182	  label,
183	  description,
184	  benefit,
185	  selected,
186	  onSelect,
187	}: {
188	  value: string;
189	  label: string;
190	  description: string;
191	  benefit: string;
192	  selected: boolean;
193	  onSelect: (v: string) => void;
194	}) {
195	  return (
196	    <Box minWidth="140px" width="100%">
197	      <div
198	        role="button"
199	        tabIndex={0}
200	        onClick={() => onSelect(value)}
201	        onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(value); } }}
202	        style={{ cursor: "pointer" }}
203	      >
204	        <Box
205	          padding="400"
206	          borderWidth={selected ? "050" : "025"}
207	          borderColor={selected ? "border-focus" : "border"}
208	          borderRadius="200"
209	          background={selected ? "bg-surface-selected" : "bg-surface"}
210	        >
211	          <BlockStack gap="200">
212	            <InlineStack gap="200" blockAlign="center">
213	              <Text as="p" variant="bodyMd" fontWeight="semibold">{label}</Text>
214	              {selected && <Badge tone="info">Active</Badge>}
215	            </InlineStack>
216	            <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
217	            <Text as="p" variant="bodyMd" tone="subdued">Best for: {benefit}</Text>
218	          </BlockStack>
219	        </Box>
220	      </div>
221	    </Box>
222	  );
223	}
224	
225	function PositionGrid({
226	  value,
227	  onChange,
228	}: {
229	  value: string;
230	  onChange: (v: string) => void;
231	}) {
232	  const positions = [
233	    { id: "top-left", label: "Top Left" },
234	    { id: "top-right", label: "Top Right" },
235	    { id: "bottom-left", label: "Bottom Left" },
236	    { id: "bottom-right", label: "Bottom Right" },
237	  ];
238	
239	  return (
240	    <Box maxWidth="320px">
241	      <InlineGrid columns={2} gap="200">
242	        {positions.map((pos) => {
243	          const isSelected = value === pos.id;
244	          return (
245	            <div
246	              key={pos.id}
247	              role="button"
248	              tabIndex={0}
249	              onClick={() => onChange(pos.id)}
250	              onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onChange(pos.id); } }}
251	              style={{ cursor: "pointer" }}
252	            >
253	              <Box
254	                padding="400"
255	                borderWidth={isSelected ? "050" : "025"}
256	                borderColor={isSelected ? "border-focus" : "border"}
257	                borderRadius="200"
258	                background={isSelected ? "bg-surface-selected" : "bg-surface"}
259	              >
260	                <Text as="p" variant="bodyMd" tone={isSelected ? undefined : "subdued"}>{pos.label}</Text>
261	              </Box>
262	            </div>
263	          );
264	        })}
265	      </InlineGrid>
266	    </Box>
267	  );
268	}
269	
270	function TriggerTypeSelector({
271	  value,
272	  onChange,
273	}: {
274	  value: string;
275	  onChange: (v: string) => void;
276	}) {
277	  const types = [
278	    { id: "button", label: "Button", desc: "Prominent CTA button" },
279	    { id: "link", label: "Link", desc: "Subtle text link" },
280	    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
281	  ];
282	
283	  return (
284	    <InlineStack gap="400">
285	      {types.map((t) => {
286	        const isSelected = value === t.id;
287	        return (
288	          <div key={t.id} role="button" tabIndex={0} onClick={() => onChange(t.id)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onChange(t.id); } }} style={{ cursor: "pointer" }}>
289	            <Box
290	              padding="400"
291	              borderWidth={isSelected ? "050" : "025"}
292	              borderColor={isSelected ? "border-focus" : "border"}
293	              borderRadius="200"
294	              background={isSelected ? "bg-surface-selected" : "bg-surface"}
295	            >
296	              <BlockStack gap="200">
297	                <Text as="p" variant="bodyMd" fontWeight="semibold">{t.label}</Text>
298	                <Text as="p" variant="bodyMd" tone="subdued">{t.desc}</Text>
299	              </BlockStack>
300	            </Box>
301	          </div>
302	        );
303	      })}
304	    </InlineStack>
305	  );
306	}
307	
308	// ---------------------------------------------------------------------------
309	// Live Preview — intentional custom styling kept as-is
310	// ---------------------------------------------------------------------------
311	
312	function WidgetPreview({ config }: { config: LocalConfig }) {
313	  const radius = `${config.borderRadius}px`;
314	
315	  return (
316	    <div
317	      style={{
318	        backgroundColor: config.backgroundColor,
319	        borderRadius: radius,
320	        border: `1px solid ${config.primaryColor}33`,
321	        padding: "20px",
322	        fontFamily: "system-ui, sans-serif",
323	        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
324	        maxWidth: "320px",
325	        width: "100%",
326	      }}
327	    >
328	      {/* Header */}
329	      <div
330	        style={{
331	          borderBottom: `1px solid ${config.primaryColor}22`,
332	          paddingBottom: "12px",
333	          marginBottom: "16px",
334	          display: "flex",
335	          alignItems: "center",
336	          justifyContent: "space-between",
337	        }}
338	      >
339	        <span
340	          style={{
341	            fontSize: "16px",
342	            fontWeight: 700,
343	            color: config.textColor,
344	          }}
345	        >
346	          {config.heading || "Size Guide"}
347	        </span>
348	        <span
349	          style={{
350	            fontSize: "18px",
351	            color: "#8c9196",
352	            cursor: "pointer",
353	            lineHeight: 1,
354	          }}
355	        >
356	          ×
357	        </span>
358	      </div>
359	
360	      {/* Size Chart Table */}
361	      <div
362	        style={{
363	          borderRadius: "6px",
364	          overflow: "hidden",
365	          border: "1px solid #e3e5e7",
366	          marginBottom: "16px",
367	        }}
368	      >
369	        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
370	          <thead>
371	            <tr style={{ backgroundColor: `${config.primaryColor}15` }}>
372	              {["Size", "S", "M", "L", "XL"].map((h) => (
373	                <th
374	                  key={h}
375	                  style={{
376	                    padding: "8px 10px",
377	                    textAlign: "center",
378	                    fontWeight: 600,
379	                    color: config.textColor,
380	                    borderRight: "1px solid #e3e5e7",
381	                  }}
382	                >
383	                  {h}
384	                </th>
385	              ))}
386	            </tr>
387	          </thead>
388	          <tbody>
389	            {[
390	              { label: "Bust", values: ["32", "34", "36", "38"] },
391	              { label: "Waist", values: ["26", "28", "30", "32"] },
392	              { label: "Hips", values: ["34", "36", "38", "40"] },
393	            ].map((row, ri) => (
394	              <tr
395	                key={row.label}
396	                style={{ backgroundColor: ri % 2 === 0 ? "#fff" : "#f9fafb" }}
397	              >
398	                <td
399	                  style={{
400	                    padding: "7px 10px",
401	                    fontWeight: 600,
402	                    color: config.textColor,
403	                    borderRight: "1px solid #e3e5e7",
404	                    borderTop: "1px solid #e3e5e7",
405	                    fontSize: "11px",
406	                  }}
407	                >
408	                  {row.label}
409	                </td>
410	                {row.values.map((v, vi) => (
411	                  <td
412	                    key={vi}
413	                    style={{
414	                      padding: "7px 10px",
415	                      textAlign: "center",
416	                      color: config.textColor,
417	                      borderRight: "1px solid #e3e5e7",
418	                      borderTop: "1px solid #e3e5e7",
419	                      fontSize: "11px",
420	                    }}
421	                  >
422	                    {v}&quot;
423	                  </td>
424	                ))}
425	              </tr>
426	            ))}
427	          </tbody>
428	        </table>
429	      </div>
430	
431	      {/* CTA Button */}
432	      {config.showRecommender && (
433	        <button
434	          style={{
435	            width: "100%",
436	            padding: "10px 16px",
437	            backgroundColor: config.primaryColor,
438	            color: "#fff",
439	            border: "none",
440	            borderRadius: radius,
441	            fontSize: "14px",
442	            fontWeight: 600,
443	            cursor: "pointer",
444	            marginBottom: "12px",
445	          }}
446	        >
447	          {config.buttonText || "Find My Size"}
448	        </button>
449	      )}
450	
451	      {/* Success Message */}
452	      <div
453	        style={{
454	          backgroundColor: `${config.successColor}15`,
455	          border: `1px solid ${config.successColor}40`,
456	          borderRadius: "6px",
457	          padding: "10px 12px",
458	          display: "flex",
459	          alignItems: "flex-start",
460	          gap: "8px",
461	        }}
462	      >
463	        <span style={{ color: config.successColor, fontSize: "14px", flexShrink: 0 }}>✓</span>
464	        <span style={{ fontSize: "12px", color: config.textColor, lineHeight: 1.4 }}>
465	          {config.successMessage || "This size should fit you well!"}
466	        </span>
467	      </div>
468	
469	      {/* Footer badge */}
470	      <div
471	        style={{
472	          marginTop: "12px",
473	          textAlign: "center",
474	          fontSize: "10px",
475	          color: "#8c9196",
476	        }}
477	      >
478	        Powered by Size Chart &amp; Recommender
479	      </div>
480	    </div>
481	  );
482	}
