484	// ---------------------------------------------------------------------------
485	// Main Component
486	// ---------------------------------------------------------------------------
487	
488	export default function WidgetCustomizer() {
489	  const { config: serverConfig } = useLoaderData<typeof loader>();
490	  const fetcher = useFetcher<typeof action>();
491	  const shopify = useAppBridge();
492	  const navigate = useNavigate();
493	
494	  const [config, setConfig] = useState<LocalConfig>({
495	    displayMode: serverConfig.displayMode,
496	    position: serverConfig.position,
497	    triggerType: serverConfig.triggerType,
498	    primaryColor: serverConfig.primaryColor,
499	    successColor: serverConfig.successColor,
500	    errorColor: serverConfig.errorColor,
501	    backgroundColor: serverConfig.backgroundColor,
502	    textColor: serverConfig.textColor,
503	    borderRadius: serverConfig.borderRadius,
504	    heading: serverConfig.heading,
505	    placeholder: serverConfig.placeholder,
506	    buttonText: serverConfig.buttonText,
507	    successMessage: serverConfig.successMessage,
508	    errorMessage: serverConfig.errorMessage,
509	    showRecommender: serverConfig.showRecommender,
510	    customCss: serverConfig.customCss,
511	  });
512	
513	  const isLoading = fetcher.state !== "idle";
514	
515	  useEffect(() => {
516	    if (fetcher.data && "ok" in fetcher.data) {
517	      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
518	    } else if (fetcher.data && "error" in fetcher.data) {
519	      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
520	    }
521	  }, [fetcher.data, shopify]);
522	
523	  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
524	    setConfig((prev) => ({ ...prev, [key]: value }));
525	  };
526	
527	  const handleSave = () => {
528	    const formData = new FormData();
529	    formData.set("displayMode", config.displayMode);
530	    formData.set("position", config.position);
531	    formData.set("triggerType", config.triggerType);
532	    formData.set("primaryColor", config.primaryColor);
533	    formData.set("successColor", config.successColor);
534	    formData.set("errorColor", config.errorColor);
535	    formData.set("backgroundColor", config.backgroundColor);
536	    formData.set("textColor", config.textColor);
537	    formData.set("borderRadius", config.borderRadius);
538	    formData.set("heading", config.heading);
539	    formData.set("placeholder", config.placeholder);
540	    formData.set("buttonText", config.buttonText);
541	    formData.set("successMessage", config.successMessage);
542	    formData.set("errorMessage", config.errorMessage);
543	    formData.set("showRecommender", config.showRecommender ? "true" : "false");
544	    formData.set("customCss", config.customCss);
545	    fetcher.submit(formData, { method: "post" });
546	  };
547	
548	  const showPosition = config.displayMode === "popup" || config.displayMode === "both";
549	
550	  return (
551	    <Page
552	      title="Widget Customizer"
553	      backAction={{ onAction: () => navigate("/app") }}
554	      primaryAction={
555	        <Button variant="primary" onClick={handleSave} loading={isLoading}>
556	          Save changes
557	        </Button>
558	      }
559	    >
560	      <Layout>
561	        <Layout.Section>
562	          <BlockStack gap="600">
563	
564	            {/* ---------------------------------------------------------------- */}
565	            {/* Section 1 — Display Mode                                         */}
566	            {/* ---------------------------------------------------------------- */}
567	            <Card>
568	              <BlockStack gap="400">
569	                <Text as="h2" variant="headingMd" fontWeight="bold">Display Mode</Text>
570	                <InlineStack gap="400" wrap>
571	                  <DisplayModeCard
572	                    value="popup"
573	                    label="Popup"
574	                    description="Opens as a modal overlay when triggered"
575	                    benefit="clean product pages"
576	                    selected={config.displayMode === "popup"}
577	                    onSelect={(v) => updateConfig("displayMode", v)}
578	                  />
579	                  <DisplayModeCard
580	                    value="inline"
581	                    label="Inline"
582	                    description="Embedded directly in the product page"
583	                    benefit="detailed size info"
584	                    selected={config.displayMode === "inline"}
585	                    onSelect={(v) => updateConfig("displayMode", v)}
586	                  />
587	                  <DisplayModeCard
588	                    value="both"
589	                    label="Both"
590	                    description="Inline summary with popup for full chart"
591	                    benefit="maximum visibility"
592	                    selected={config.displayMode === "both"}
593	                    onSelect={(v) => updateConfig("displayMode", v)}
594	                  />
595	                </InlineStack>
596	              </BlockStack>
597	            </Card>
598	
599	            {/* ---------------------------------------------------------------- */}
600	            {/* Section 2 — Trigger Settings                                     */}
601	            {/* ---------------------------------------------------------------- */}
602	            <Card>
603	              <BlockStack gap="400">
604	                <Text as="h2" variant="headingMd" fontWeight="bold">Trigger Settings</Text>
605	                <BlockStack gap="400">
606	                  <BlockStack gap="200">
607	                    <Text as="p" variant="bodyMd">Trigger style</Text>
608	                    <TriggerTypeSelector
609	                      value={config.triggerType}
610	                      onChange={(v) => updateConfig("triggerType", v)}
611	                    />
612	                  </BlockStack>
613	
614	                  {showPosition && (
615	                    <BlockStack gap="200">
616	                      <Text as="p" variant="bodyMd">Popup position</Text>
617	                      <PositionGrid
618	                        value={config.position}
619	                        onChange={(v) => updateConfig("position", v)}
620	                      />
621	                    </BlockStack>
622	                  )}
623	                </BlockStack>
624	              </BlockStack>
625	            </Card>
626	
627	            {/* ---------------------------------------------------------------- */}
628	            {/* Section 3 — Colors                                               */}
629	            {/* ---------------------------------------------------------------- */}
630	            <Card>
631	              <BlockStack gap="400">
632	                <Text as="h2" variant="headingMd" fontWeight="bold">Colors</Text>
633	                <InlineStack gap="400" wrap>
634	                  <ColorPickerField
635	                    label="Primary Color"
636	                    value={config.primaryColor}
637	                    onChange={(v) => updateConfig("primaryColor", v)}
638	                  />
639	                  <ColorPickerField
640	                    label="Background Color"
641	                    value={config.backgroundColor}
642	                    onChange={(v) => updateConfig("backgroundColor", v)}
643	                  />
644	                  <ColorPickerField
645	                    label="Text Color"
646	                    value={config.textColor}
647	                    onChange={(v) => updateConfig("textColor", v)}
648	                  />
649	                  <ColorPickerField
650	                    label="Success Color"
651	                    value={config.successColor}
652	                    onChange={(v) => updateConfig("successColor", v)}
653	                  />
654	                  <ColorPickerField
655	                    label="Error Color"
656	                    value={config.errorColor}
657	                    onChange={(v) => updateConfig("errorColor", v)}
658	                  />
659	                </InlineStack>
660	              </BlockStack>
661	            </Card>
662	
663	            {/* ---------------------------------------------------------------- */}
664	            {/* Section 4 — Typography & Spacing                                 */}
665	            {/* ---------------------------------------------------------------- */}
666	            <Card>
667	              <BlockStack gap="400">
668	                <Text as="h2" variant="headingMd" fontWeight="bold">Typography &amp; Spacing</Text>
669	                <BlockStack gap="400">
670	                  <RangeSlider
671	                    label="Border Radius (px)"
672	                    value={Number(config.borderRadius) || 0}
673	                    min={0}
674	                    max={24}
675	                    step={1}
676	                    output
677	                    suffix={
678	                      <Box minWidth="48px">
679	                        <TextField
680	                          label="Border radius value"
681	                          labelHidden
682	                          type="number"
683	                          value={config.borderRadius}
684	                          onChange={(val) => {
685	                            const num = Math.max(0, Math.min(24, Number(val) || 0));
686	                            updateConfig("borderRadius", String(num));
687	                          }}
688	                          autoComplete="off"
689	                        />
690	                      </Box>
691	                    }
