24	// Types
25	// ---------------------------------------------------------------------------
26	
27	interface DailyDataPoint {
28	  label: string;
29	  value: number;
30	}
31	
32	interface TopChart {
33	  chartId: string | null;
34	  chartName: string;
35	  views: number;
36	  rank: number;
37	}
