import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Banner,
  Box,
  Tooltip,
  Divider,
  TextField,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";
import {
  getAnalyticsSummary,
  getConversionFunnel,
  getTopCharts,
  getDailyTrend,
  buildDateRange,
  type AnalyticsSummary,
  type ConversionFunnel,
  type ChartPerformance,
  type DailyDataPoint,
} from "../lib/analytics.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface AnalyticsData {
  summary: AnalyticsSummary;
  summaryPrev: AnalyticsSummary;
  funnel: ConversionFunnel;
  topCharts: ChartPerformance[];
  dailyTrend: DailyDataPoint[];
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const url = new URL(request.url);
  const fromParam = url.searchParams.get("from");
  const toParam = url.searchParams.get("to");
  const presetParam = url.searchParams.get("preset") ?? "30d";

  // Resolve current date range
  const now = new Date();
  let fromDate: Date;
  let toDate: Date = new Date(now);
  toDate.setHours(23, 59, 59, 999);

  if (fromParam && toParam) {
    fromDate = new Date(fromParam);
    fromDate.setHours(0, 0, 0, 0);
    const parsedTo = new Date(toParam);
    parsedTo.setHours(23, 59, 59, 999);
    toDate = parsedTo;
  } else {
    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
    fromDate.setHours(0, 0, 0, 0);
  }

  const dateRange = { from: fromDate, to: toDate };

  // Previous period for trend comparison (same duration, shifted back)
  const rangeMs = toDate.getTime() - fromDate.getTime();
  const prevToDate = new Date(fromDate.getTime() - 1);
  prevToDate.setHours(23, 59, 59, 999);
  const prevFromDate = new Date(prevToDate.getTime() - rangeMs);
  prevFromDate.setHours(0, 0, 0, 0);
  const prevDateRange = { from: prevFromDate, to: prevToDate };

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const plan = getPlan(subscription?.planId ?? "free");
  const canViewAnalytics = hasFeature(plan.id, "analytics");

  if (!canViewAnalytics) {
    return {
      plan,
      canViewAnalytics: false as const,
      analytics: null,
      preset: presetParam,
      fromDate: fromDate.toISOString().split("T")[0],
      toDate: toDate.toISOString().split("T")[0],
    };
  }

  // Fetch all analytics data using the server helpers
  const [summary, summaryPrev, funnel, topCharts, dailyTrend] = await Promise.all([
    getAnalyticsSummary(shop, dateRange),
    getAnalyticsSummary(shop, prevDateRange),
    getConversionFunnel(shop, dateRange),
    getTopCharts(shop, dateRange, 5),
    getDailyTrend(shop, dateRange, "view"),
  ]);

  const analytics: AnalyticsData = {
    summary,
    summaryPrev,
    funnel,
    topCharts,
    dailyTrend,
  };

  return {
    plan,
    canViewAnalytics: true as const,
    analytics,
    preset: presetParam,
    fromDate: fromDate.toISOString().split("T")[0],
    toDate: toDate.toISOString().split("T")[0],
  };
};

// ---------------------------------------------------------------------------
// StatCard — single metric with trend
// ---------------------------------------------------------------------------

function StatCard({
  label,
  value,
  prevValue,
  isLoading,
}: {
  label: string;
  value: number;
  prevValue: number;
  isLoading: boolean;
}) {
  const diff = value - prevValue;
  const pct = prevValue > 0 ? Math.round((diff / prevValue) * 100) : 0;
  const isUp = diff >= 0;

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor="border"
      borderRadius="200"
      padding="400"
    >
      <BlockStack gap="100">
        <Text as="p" variant="bodySm" tone="subdued">{label}</Text>
        <Text as="p" variant="headingXl" fontWeight="bold">
          {isLoading ? "—" : value.toLocaleString()}
        </Text>
        {!isLoading && prevValue > 0 && (
          <InlineStack gap="100" blockAlign="center">
            <Text
              as="span"
              variant="bodySm"
              tone={isUp ? "success" : "critical"}
            >
              {isUp ? "+" : ""}{pct}%
            </Text>
            <Text as="span" variant="bodySm" tone="subdued">vs prior period</Text>
          </InlineStack>
        )}
        {!isLoading && prevValue === 0 && (
          <Text as="p" variant="bodySm" tone="subdued">No prior data</Text>
        )}
      </BlockStack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// BarChart — daily views visualization
// ---------------------------------------------------------------------------

function BarChart({ data, isLoading }: { data: DailyDataPoint[]; isLoading: boolean }) {
  if (isLoading) {
    return (
      <div style={{ height: "250px", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Text as="p" variant="bodyMd" tone="subdued">Loading chart data…</Text>
      </div>
    );
  }

  const max = Math.max(...data.map((d) => d.count), 1);

  // For readability, show at most 30 data points — group into weekly if needed
  let displayData = data;
  if (data.length > 30) {
    const weekBuckets: Record<string, number> = {};
    for (const pt of data) {
      const d = new Date(pt.date + "T12:00:00Z");
      const weekStart = new Date(d);
      weekStart.setDate(d.getDate() - d.getDay());
      const wk = weekStart.toISOString().slice(0, 10);
      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + pt.count;
    }
    displayData = Object.entries(weekBuckets).map(([date, count]) => ({ date, count }));
  }

  const formatLabel = (dateStr: string) =>
    new Date(dateStr + "T12:00:00Z").toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
    });

  return (
    <BlockStack gap="200">
      <div style={{ display: "flex", alignItems: "flex-end", gap: "3px", height: "200px" }}>
        {displayData.map((d, i) => (
          <Tooltip key={i} content={`${formatLabel(d.date)}: ${d.count} views`}>
            <div
              style={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                justifyContent: "flex-end",
                height: "200px",
              }}
            >
              <div
                style={{
                  background: "var(--p-color-bg-fill-brand)",
                  borderRadius: "3px 3px 0 0",
                  height: `${Math.max((d.count / max) * 200, d.count > 0 ? 4 : 0)}px`,
                  minHeight: d.count > 0 ? "4px" : "0",
                  transition: "height 0.2s ease",
                }}
              />
            </div>
          </Tooltip>
        ))}
      </div>
      <InlineStack align="space-between">
        <Text as="p" variant="bodySm" tone="subdued">
          {displayData[0] ? formatLabel(displayData[0].date) : ""}
        </Text>
        <Text as="p" variant="bodySm" tone="subdued">
          {displayData[displayData.length - 1] ? formatLabel(displayData[displayData.length - 1].date) : ""}
        </Text>
      </InlineStack>
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
// FunnelStep — single step in the conversion funnel
// ---------------------------------------------------------------------------

function FunnelStep({
  label,
  count,
  rate,
  color,
  isLoading,
}: {
  label: string;
  count: number;
  rate: number;
  color: string;
  isLoading: boolean;
}) {
  const pct = Math.round(rate * 100 * 10) / 10;
  const barWidth = Math.min(100, pct);
  const tone = pct >= 30 ? "success" : pct >= 10 ? "info" : "warning";

  return (
    <BlockStack gap="200">
      <InlineStack gap="300" align="space-between" blockAlign="center">
        <Text as="p" variant="bodyMd">{label}</Text>
        <InlineStack gap="200" blockAlign="center">
          <Text as="p" variant="bodyMd" tone="subdued">
            {isLoading ? "—" : count.toLocaleString()}
          </Text>
          <Badge tone={tone}>{isLoading ? "—" : `${pct}%`}</Badge>
        </InlineStack>
      </InlineStack>
      <Box
        background="bg-fill-secondary"
        borderRadius="150"
        minHeight="8px"
      >
        <div
          style={{
            height: "8px",
            width: `${barWidth}%`,
            background: color,
            borderRadius: "var(--p-border-radius-150)",
            transition: "width 0.4s ease",
          }}
        />
      </Box>
    </BlockStack>
  );
}

// ---------------------------------------------------------------------------
