// ---------------------------------------------------------------------------
// CSV export helper (runs in browser)
// ---------------------------------------------------------------------------

function exportCsv(data: AnalyticsData, preset: string) {
  const rows: string[] = [
    "Date,Views",
    ...data.dailyTrend.map((pt) => `${pt.date},${pt.count}`),
    "",
    "Metric,Value",
    `Total Views,${data.summary.totalViews}`,
    `Total Clicks,${data.summary.totalClicks}`,
    `Total Recommendations,${data.summary.totalRecommendations}`,
    `Total Conversions,${data.summary.totalConversions}`,
    "",
    "Rank,Chart,Views,Clicks,Recommendations,Conversions",
    ...data.topCharts.map(
      (c, i) =>
        `${i + 1},${c.name},${c.views},${c.clicks},${c.recommendations},${c.conversions}`,
    ),
  ];

  const blob = new Blob([rows.join("\n")], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `size-chart-analytics-${preset}-${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

