// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface BodyTypeConfig {
  id: string;
  label: string;
  description: string;
  enabled: boolean;
}

interface TestResult {
  size: string;
  confidence: number;
  alternatives: string[];
  bust: number;
  waist: number;
  hips: number;
}

const DEFAULT_BODY_TYPES: BodyTypeConfig[] = [
  { id: "slim", label: "Slim", description: "Narrower proportions, prefers fitted styles", enabled: true },
  { id: "regular", label: "Regular", description: "Standard proportions, true-to-size fits well", enabled: true },
  { id: "athletic", label: "Athletic", description: "Broader chest/shoulders, narrower waist", enabled: true },
  { id: "plus", label: "Plus", description: "Fuller proportions, relaxed fit preferences", enabled: true },
  { id: "petite", label: "Petite", description: "Shorter stature, petite-specific proportions", enabled: false },
];

const DEFAULT_FIT_PREFERENCE = "true-to-size";
const DEFAULT_ALGORITHM = "basic";

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [config, subscription, charts] = await Promise.all([
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop, status: "active" },
      select: { id: true, name: true, category: true },
      orderBy: { name: "asc" },
    }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const canUseAi = hasFeature(plan.id, "aiRecommender");
  const canUseAdvanced = hasFeature(plan.id, "advancedAi");

  let bodyTypes = DEFAULT_BODY_TYPES;
  if (config?.bodyTypes) {
    try {
      const saved = JSON.parse(config.bodyTypes) as Array<{ id: string; enabled: boolean }>;
      bodyTypes = DEFAULT_BODY_TYPES.map((bt) => {
        const match = saved.find((s) => s.id === bt.id);
        return match ? { ...bt, enabled: match.enabled } : bt;
      });
    } catch {
      bodyTypes = DEFAULT_BODY_TYPES;
    }
  }

  let sizingRules: Record<string, string> = {};
  if (config?.sizingRules) {
    try {
      sizingRules = JSON.parse(config.sizingRules) as Record<string, string>;
    } catch {
      sizingRules = {};
    }
  }

  const fitPreference = (sizingRules.fitPreference as string) ?? DEFAULT_FIT_PREFERENCE;
  const betweenSizes = (sizingRules.betweenSizes as string) ?? "larger";

  return {
    config: {
      enabled: config?.enabled ?? false,
      algorithm: config?.algorithm ?? DEFAULT_ALGORITHM,
    },
    bodyTypes,
    fitPreference,
    betweenSizes,
    plan,
    canUseAi,
    canUseAdvanced,
    charts,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "toggle": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher", intent };
        }
        const current = await db.recommenderConfig.findUnique({ where: { shop } });
        const newEnabled = !current?.enabled;
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { enabled: newEnabled },
          create: { shop, enabled: newEnabled },
        });
        return {
          ok: true,
          intent,
          enabled: newEnabled,
          message: newEnabled ? "AI Recommender enabled" : "AI Recommender disabled",
        };
      }

      case "update-settings": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher", intent };
        }
        const algorithm = (formData.get("algorithm") as string) || DEFAULT_ALGORITHM;
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { algorithm },
          create: { shop, algorithm },
        });
        return { ok: true, intent, message: "Algorithm updated" };
      }

      case "save-body-types": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher", intent };
        }
        const bodyTypesRaw = formData.get("bodyTypes") as string;
        if (!bodyTypesRaw) return { error: "No body types data", intent };
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { bodyTypes: bodyTypesRaw },
          create: { shop, bodyTypes: bodyTypesRaw },
        });
        return { ok: true, intent, message: "Body types saved" };
      }

      case "save-sizing-rules": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher", intent };
        }
        const fitPreference = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
        const betweenSizes = (formData.get("betweenSizes") as string) || "larger";
        const rules = JSON.stringify({ fitPreference, betweenSizes });
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { sizingRules: rules },
          create: { shop, sizingRules: rules },
        });
        return { ok: true, intent, message: "Sizing rules saved" };
      }

      case "test-recommendation": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher", intent };
        }

        const heightCm = parseFloat(formData.get("height") as string);
        const weightKg = parseFloat(formData.get("weight") as string);
        const bodyType = (formData.get("bodyType") as string) || "regular";
        const fitPref = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;

        if (
          isNaN(heightCm) ||
          isNaN(weightKg) ||
          heightCm < 100 ||
          heightCm > 250 ||
          weightKg < 30 ||
          weightKg > 250
        ) {
          return {
            error: "Please enter valid height (100–250 cm) and weight (30–250 kg)",
            intent,
          };
        }

        const bmi = weightKg / (heightCm / 100) ** 2;

        const bodyTypeMultipliers: Record<string, { bust: number; waist: number; hips: number }> = {
          slim:     { bust: 0.52, waist: 0.43, hips: 0.54 },
          regular:  { bust: 0.54, waist: 0.46, hips: 0.57 },
          athletic: { bust: 0.56, waist: 0.44, hips: 0.56 },
          plus:     { bust: 0.59, waist: 0.52, hips: 0.62 },
          petite:   { bust: 0.52, waist: 0.44, hips: 0.55 },
        };

        const fitBias: Record<string, number> = {
          tight:          -2,
          "true-to-size": 0,
          relaxed:        2,
          oversized:      4,
        };

        const mult = bodyTypeMultipliers[bodyType] ?? bodyTypeMultipliers.regular;
        const bias = fitBias[fitPref] ?? 0;

        const bust  = Math.round(heightCm * mult.bust + bias);
        const waist = Math.round(heightCm * mult.waist + (bmi - 22) * 0.5 + bias);
        const hips  = Math.round(heightCm * mult.hips + bias);

        const sizes = [
          { label: "XS",  bustMin: 76,  bustMax: 83  },
          { label: "S",   bustMin: 84,  bustMax: 91  },
          { label: "M",   bustMin: 92,  bustMax: 99  },
          { label: "L",   bustMin: 100, bustMax: 107 },
          { label: "XL",  bustMin: 108, bustMax: 115 },
          { label: "2XL", bustMin: 116, bustMax: 123 },
          { label: "3XL", bustMin: 124, bustMax: 131 },
        ];

        const matched    = sizes.find((s) => bust >= s.bustMin && bust <= s.bustMax);
        const matchedIdx = matched ? sizes.indexOf(matched) : 2;
        const size       = matched?.label ?? "M";
        const confidence = matched
          ? Math.round(90 - Math.abs(bust - (matched.bustMin + matched.bustMax) / 2) * 0.8)
          : 65;

        const alternatives: string[] = [];
        if (matchedIdx > 0) alternatives.push(sizes[matchedIdx - 1].label);
        if (matchedIdx < sizes.length - 1) alternatives.push(sizes[matchedIdx + 1].label);

        return {
          ok: true,
          intent,
          testResult: { size, confidence, alternatives, bust, waist, hips } as TestResult,
          message: `Recommended size: ${size}`,
        };
      }

      default:
        return { error: "Unknown action", intent };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message, intent };
  }
};

