function AlgorithmCard({
  id,
  label,
  description,
  badge,
  badgeTone,
  selected,
  disabled,
  onSelect,
}: {
  id: string;
  label: string;
  description: string;
  badge: string;
  badgeTone: "success" | "warning" | "info";
  selected: boolean;
  disabled: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      onClick={() => !disabled && onSelect(id)}
