                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd">Default fit preference</Text>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "8px" }}>
                    {fitOptions.map((opt) => {
                      const isSelected = fitPreference === opt.value;
                      return (
                        <div
                          key={opt.value}
                          role="button"
                          tabIndex={0}
                          onClick={() => setFitPreference(opt.value)}
                          onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                              e.preventDefault();
                              setFitPreference(opt.value);
                            }
                          }}
                          style={{ cursor: "pointer" }}
                        >
                          <Box
                            padding="300"
                            borderWidth={isSelected ? "050" : "025"}
                            borderColor={isSelected ? "border-focus" : "border"}
                            borderRadius="200"
                            background={isSelected ? "bg-surface-selected" : "bg-surface"}
                          >
                            <Text
                              as="p"
                              variant="bodySm"
                              fontWeight={isSelected ? "semibold" : "regular"}
                              alignment="center"
                            >
                              {opt.label}
                            </Text>
                          </Box>
                        </div>
                      );
                    })}
                  </div>
                </BlockStack>

                <InlineStack gap="200">
                  <Button
                    variant="primary"
                    onClick={submitSizingRules}
                    loading={isLoading && fetcher.formData?.get("intent") === "save-sizing-rules"}
                  >
                    Save preferences
                  </Button>
                </InlineStack>
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Test Interface                                                */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Test Interface</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    Enter sample customer inputs to preview what your recommender would suggest.
                    This uses your saved algorithm and sizing rules.
                  </Text>
                </BlockStack>

                {/* Chart + gender + body type selectors */}
                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Chart to test</Text>
                    {charts.length === 0 ? (
                      <InlineStack gap="200" blockAlign="center">
                        <Text as="p" variant="bodyMd" tone="subdued">No active charts.</Text>
                        <Button variant="plain" onClick={() => navigate("/app/size-charts")}>
                          Create one
                        </Button>
                      </InlineStack>
                    ) : (
                      <Select
                        label="Chart"
                        labelHidden
                        options={chartOptions}
                        value={testChartId}
                        onChange={(value) => setTestChartId(value)}
                      />
                    )}
                  </BlockStack>

                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Gender</Text>
                    <Select
                      label="Gender"
                      labelHidden
                      options={genderOptions}
                      value={testGender}
                      onChange={(value) => setTestGender(value)}
                    />
                  </BlockStack>

                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Body type</Text>
                    <Select
                      label="Body type"
                      labelHidden
                      options={enabledBodyTypeOptions}
                      value={testBodyType}
                      onChange={(value) => setTestBodyType(value)}
                    />
                  </BlockStack>
                </InlineGrid>

                {/* Height + weight */}
                <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                  <TextField
                    label="Height (cm)"
                    type="number"
                    value={testHeight}
                    onChange={(value) => setTestHeight(value)}
                    autoComplete="off"
                    min={100}
                    max={250}
                  />
                  <TextField
                    label="Weight (kg)"
                    type="number"
                    value={testWeight}
                    onChange={(value) => setTestWeight(value)}
                    autoComplete="off"
                    min={30}
                    max={250}
                  />
                </InlineGrid>

                <Button
                  variant="primary"
                  onClick={submitTestRecommendation}
                  loading={isLoading && fetcher.formData?.get("intent") === "test-recommendation"}
                  disabled={charts.length === 0}
                >
                  Get Recommendation
                </Button>

                {/* Result */}
                {testResult && (
                  <>
                    <Divider />
                    <BlockStack gap="300">
                      <InlineStack gap="300" blockAlign="center">
                        <Text as="p" variant="headingXl" fontWeight="bold">{testResult.size}</Text>
                        <Badge
                          tone={
                            testResult.confidence >= 85
                              ? "success"
                              : testResult.confidence >= 70
                              ? "info"
                              : "warning"
                          }
                        >
                          {testResult.confidence}% confidence
                        </Badge>
                      </InlineStack>

                      {testResult.alternatives.length > 0 && (
                        <InlineStack gap="200" blockAlign="center">
                          <Text as="p" variant="bodySm" tone="subdued">Alternatives:</Text>
                          {testResult.alternatives.map((alt) => (
                            <Badge key={alt} tone="new">{alt}</Badge>
                          ))}
                        </InlineStack>
                      )}

                      <Text as="p" variant="bodySm" tone="subdued">Estimated measurements</Text>
                      <InlineGrid columns={{ xs: 3 }} gap="400">
                        {[
                          { label: "Bust",  value: testResult.bust },
                          { label: "Waist", value: testResult.waist },
                          { label: "Hips",  value: testResult.hips },
                        ].map((m) => (
                          <Box
                            key={m.label}
                            borderWidth="025"
                            borderColor="border"
                            borderRadius="200"
                            padding="300"
                            background="bg-surface"
                          >
                            <BlockStack gap="050">
                              <Text as="p" variant="bodySm" tone="subdued">{m.label}</Text>
                              <Text as="p" variant="bodyMd" fontWeight="semibold">{m.value} cm</Text>
                            </BlockStack>
                          </Box>
                        ))}
                      </InlineGrid>

                      {charts.length > 0 && (
                        <Text as="p" variant="bodySm" tone="subdued">
                          Tested against:{" "}
                          {charts.find((c) => c.id === testChartId)?.name ?? "—"}
                        </Text>
                      )}
                    </BlockStack>
                  </>
                )}
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Active Charts                                                  */}
            {/* ============================================================ */}
            <Card>
              <BlockStack gap="400">
                <BlockStack gap="100">
                  <Text as="h2" variant="headingMd" fontWeight="semibold">Active Charts</Text>
                  <Text as="p" variant="bodySm" tone="subdued">
                    These charts are published and available for recommendations.
                  </Text>
                </BlockStack>

                {charts.length === 0 ? (
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd" tone="subdued">
                      No active size charts. Publish a chart to enable recommendations.
                    </Text>
                    <Button
                      variant="primary"
                      onClick={() => navigate("/app/size-charts")}
                    >
                      Manage size charts
                    </Button>
                  </BlockStack>
                ) : (
                  <BlockStack gap="200">
                    {charts.map((c) => (
                      <Box
                        key={c.id}
                        borderWidth="025"
                        borderColor="border"
                        borderRadius="200"
                        padding="300"
                        background="bg-surface"
                      >
                        <InlineStack align="space-between" blockAlign="center">
                          <InlineStack gap="200" blockAlign="center">
                            <Badge tone="success">Active</Badge>
                            <Text as="p" variant="bodyMd">{c.name}</Text>
                          </InlineStack>
                          <Text as="p" variant="bodySm" tone="subdued">{c.category}</Text>
                        </InlineStack>
                      </Box>
                    ))}
                  </BlockStack>
                )}
              </BlockStack>
            </Card>

            {/* ============================================================ */}
            {/* Plan + performance bar                                         */}
            {/* ============================================================ */}
            <Card>
              <InlineStack gap="400" blockAlign="center" wrap>
                <InlineStack gap="200" blockAlign="center">
                  <Badge tone="success">{plan.name}</Badge>
                  <Text as="p" variant="bodySm" tone="subdued">${plan.price}/mo</Text>
                </InlineStack>
                <Divider />
                <Text as="p" variant="bodySm" tone="subdued">Basic: ~5ms</Text>
                <Text as="p" variant="bodySm" tone="subdued">Advanced: ~50ms</Text>
                <Text as="p" variant="bodySm" tone="subdued">$0/recommendation</Text>
                <Badge tone="success">GDPR compliant</Badge>
                {!canUseAdvanced && (
                  <Button size="slim" onClick={() => navigate("/app/pricing")}>
                    Upgrade for Advanced ML
                  </Button>
                )}
              </InlineStack>
            </Card>

          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}
